function validate([land]) {
  if (!Array.isArray(land) || land.length < 2 || land.length > 100) return 'land needs 2 to 100 rows.';
  const cols = Array.isArray(land[0]) ? land[0].length : 0;
  if (cols < 2 || cols > 100) return 'Each row needs 2 to 100 cells.';
  let starts = 0, targets = 0;
  for (const row of land) {
    if (!Array.isArray(row) || row.length !== cols) return 'All rows must have the same length.';
    for (const cell of row) {
      if (!['S', 'D', '.', '*', 'X'].includes(cell)) return 'Cells are "S", "D", ".", "*" or "X".';
      if (cell === 'S') starts++;
      if (cell === 'D') targets++;
    }
  }
  if (starts !== 1) return 'land needs exactly one "S".';
  if (targets !== 1) return 'land needs exactly one "D".';
  return null;
}

