function minimumSeconds(land) {
  const rows = land.length;
  const cols = land[0].length;
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const floodTime = Array.from({ length: rows }, () => new Array(cols).fill(Infinity));
  const water = [];
  let start = null;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (land[r][c] === '*') {
        floodTime[r][c] = 0;
        water.push([r, c]);
      } else if (land[r][c] === 'S') {
        start = [r, c];
      }
    }
  }
  for (let head = 0; head < water.length; head++) {
    const [r, c] = water[head];
    for (const [dr, dc] of directions) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
      if (land[nr][nc] === 'X' || land[nr][nc] === 'D') continue;
      if (floodTime[nr][nc] !== Infinity) continue;
      floodTime[nr][nc] = floodTime[r][c] + 1;
      water.push([nr, nc]);
    }
  }
  const seconds = Array.from({ length: rows }, () => new Array(cols).fill(-1));
  seconds[start[0]][start[1]] = 0;
  const queue = [start];
  for (let head = 0; head < queue.length; head++) {
    const [r, c] = queue[head];
    if (land[r][c] === 'D') return seconds[r][c];
    for (const [dr, dc] of directions) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
      if (land[nr][nc] === 'X' || seconds[nr][nc] !== -1) continue;
      const arrival = seconds[r][c] + 1;
      if (arrival >= floodTime[nr][nc]) continue;
      seconds[nr][nc] = arrival;
      queue.push([nr, nc]);
    }
  }
  return -1;
}

