function minimumSeconds(land) {
  // Simulate second by second: spread the water, then move every possible position of the walker.
  const rows = land.length, cols = land[0].length;
  const near = (r, c) => [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]].filter(([a, b]) => a >= 0 && a < rows && b >= 0 && b < cols);
  let grid = land.map(row => [...row]);
  let here = [];
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) if (land[r][c] === 'S') here.push([r, c]);
  for (let t = 1; t <= rows * cols; t++) {
    const next = grid.map(row => [...row]);
    for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
      if (grid[r][c] !== '*') continue;
      for (const [a, b] of near(r, c)) if (next[a][b] === '.' || next[a][b] === 'S') next[a][b] = '*';
    }
    grid = next;
    const seen = new Set();
    const moved = [];
    for (const [r, c] of here) for (const [a, b] of near(r, c)) {
      if (grid[a][b] === 'X' || grid[a][b] === '*' || seen.has(a * cols + b)) continue;
      if (grid[a][b] === 'D') return t;
      seen.add(a * cols + b);
      moved.push([a, b]);
    }
    if (moved.length === 0) return -1;
    here = moved;
  }
  return -1;
}

