function generate(rand, size) {
  const large = size === 'large';
  const rows = large ? 60 + Math.floor(rand() * 41) : 2 + Math.floor(rand() * 4);
  const cols = large ? 60 + Math.floor(rand() * 41) : 2 + Math.floor(rand() * 4);
  const stone = rand() * (large ? 0.3 : 0.35);
  const flood = large ? 0 : rand() * 0.25;
  const land = Array.from({ length: rows }, () => Array.from({ length: cols }, () => {
    const x = rand();
    return x < stone ? 'X' : x < stone + flood ? '*' : '.';
  }));
  const cells = rows * cols;
  if (large) {
    // A few scattered water sources keep long walks possible on a big grid.
    const sources = Math.floor(rand() * 4);
    for (let i = 0; i < sources; i++) {
      const at = Math.floor(rand() * cells);
      land[Math.floor(at / cols)][at % cols] = '*';
    }
  }
  const s = Math.floor(rand() * cells);
  let d = Math.floor(rand() * (cells - 1));
  if (d >= s) d++;
  land[Math.floor(s / cols)][s % cols] = 'S';
  land[Math.floor(d / cols)][d % cols] = 'D';
  return [land];
}
